<script lang="ts">
    import { serverMessage } from '$lib/utils/serverMessages';
    import { Package, FileArchive, Image, Globe, FolderOpen } from 'lucide-svelte';
    import ServerResourcePacks from './ServerResourcePacks.svelte';
    import ServerContentCards from './ServerContentCards.svelte';
    import ServerFileBrowser from './ServerFileBrowser.svelte';
    import { onMount } from 'svelte';
    import { open } from '@tauri-apps/plugin-dialog';
    import { translateUi as t } from '$lib/i18n/useTranslation.svelte';
    import { button } from './serverButton';
    import { serverManage, openLocalServerFolder, type ServerContent } from '$lib/api/localServers';
    import { modsSearch } from '$lib/api/mods';
    import type { ModSearchResultItem } from '$lib/api/types';
    import { profiles } from '$lib/stores/profiles.svelte';
    let { id, mcVersion, running, pro }: { id: string; mcVersion: string; running: boolean; pro: boolean } = $props();
    let items = $state<ServerContent[]>([]); let kind = $state('mod'); let query = $state(''); let source = $state('modrinth'); let results = $state<ModSearchResultItem[]>([]); let busy = $state(false); let error = $state(''); let message = $state(''); let confirmWorld = $state(''); let ready = $state(false); let disposed = false;
    let report = $state<{prepared:number;excluded:string[];localCopy:boolean;resourcePackWarning?:string}>({prepared:0,excluded:[],localCopy:false}); let hasWorld = $state(false);
    const kinds=[{id:'mod',icon:Package},{id:'datapack',icon:FileArchive},{id:'resourcepack',icon:Image},{id:'world',icon:Globe},{id:'files',icon:FolderOpen}];
    let sourceProfile = $state(''); let preserved = $state<string[]>([]);
    function category(item: ServerContent) { if (item.kind !== 'modpack') return item.kind; return item.name.startsWith('mods/') ? 'mod' : item.name.startsWith('world/datapacks/') || item.name.startsWith('datapacks/') ? 'datapack' : item.name.startsWith('resourcepacks/') ? 'resourcepack' : 'files'; }
    const visible = $derived(items.filter(item => category(item) === kind));
    const pending = $derived(items.filter(item => item.staged).length);
    async function load() {
        const [next, imported, root] = await Promise.all([
            serverManage<ServerContent[]>({ action: 'contents', id }),
            serverManage<typeof report | null>({ action: 'instance_report', id }),
            serverManage<{entries:{name:string;directory:boolean}[]} | null>({ action: 'browse_files', id, path: '' })
        ]);
        if (!disposed) { items = next || []; report = imported || {prepared:0,excluded:[],localCopy:false}; hasWorld = Boolean(root?.entries.some(entry => entry.name === 'world' && entry.directory)); ready = true; }
    }
    onMount(() => { void load().catch(cause => { if (!disposed) error = serverMessage(cause); }); return () => { disposed = true; }; });
    async function act(action: () => Promise<unknown>, feedback = 'serverPanel.stagedHelp') { if (busy) return; busy = true; error = ''; message = ''; try { const result = await action(); if (!disposed) { message = t(result && typeof result === 'object' && 'noRequiredServerFiles' in result && result.noRequiredServerFiles ? 'serverPanel.noRequiredServerFiles' : feedback); await load(); } } catch (cause) { if (!disposed) error = serverMessage(cause); } finally { if (!disposed) busy = false; } }
    async function apply() { preserved = []; await act(async () => { const result = await serverManage<{ applied: number; preserved: string[] }>({ action: 'apply_content', id }); if (!disposed) preserved = result?.preserved || []; }, 'serverPanel.applied'); }
    async function choose() { const path = await open({ multiple: false, filters: [{ name: kind === 'mod' ? 'JAR' : 'ZIP', extensions: [kind === 'mod' ? 'jar' : 'zip'] }] }); if (typeof path === 'string') await act(() => serverManage({ action: 'import_content', id, kind, path })); }
    async function search() { await act(async () => { const next = await modsSearch(query, mcVersion, 12, 0, kind, 'downloads', undefined, undefined, source); if (!disposed) results = next; }, 'serverPanel.searchHelp'); }
    async function world() { const path = await open({ directory: true, multiple: false }); if (typeof path === 'string') confirmWorld = path; }
</script>

<section class="space-y-5 p-5 sm:p-6">
    <div><h3 class="font-semibold">{t('serverPanel.contents')}</h3><p class="mt-2 text-sm leading-6 text-fg-muted">{t('serverPanel.contentHelp')}</p></div>
    {#if report.localCopy || report.prepared || report.excluded.length}<div class="rounded-xl border border-border bg-bg-subtle p-4"><div class="flex flex-wrap items-center justify-between gap-3"><h4 class="text-sm font-semibold">{t('hosting.importSummary')}</h4><span class="text-xs tabular-nums text-fg-muted">{report.prepared} · {t('hosting.importedFiles')}</span></div>{#if report.excluded.length}<details class="mt-3 border-t border-border pt-3"><summary class="cursor-pointer text-sm font-medium text-brand-400">{t('hosting.clientExcluded')} ({report.excluded.length})</summary><p class="mt-2 text-xs leading-6 text-fg-muted">{t('hosting.clientHelp')}</p><ul class="mt-3 space-y-2">{#each report.excluded as name}<li class="break-all font-mono text-xs text-fg-muted">{name.replace(/^mods\//,'')}</li>{/each}</ul></details>{/if}</div>{/if}
    {#if report.resourcePackWarning}<p role="status" class="rounded-xl border border-warning/30 p-4 text-sm text-warning">{serverMessage(report.resourcePackWarning)}</p>{/if}
    {#if error}<p role="alert" class="break-words rounded-xl border border-danger/30 p-3 text-sm text-danger">{error}</p>{/if}{#if message}<p role="status" class="text-sm leading-6 text-success">{message}</p>{/if}
    {#if preserved.length}<p role="status" class="rounded-xl border border-warning/25 p-4 text-sm leading-6 text-warning">{t('serverPanel.preservedConfigs')} {preserved.join(', ')}</p>{/if}
    <div class="content-kinds" aria-label={t('serverPanel.contentKind')}>{#each kinds as item}{@const type=item.id}<button type="button" aria-label={t(`serverPanel.kind_${type}`)} aria-pressed={kind === type} class="content-kind" onclick={() => { kind = type; results = []; message = ''; }}><item.icon class="h-5 w-5" /><span>{t(`serverPanel.kind_${type}`)}</span>{#if type !== 'files'}<small>{type === 'world' ? hasWorld ? 1 : 0 : items.filter(item => category(item) === type).length}</small>{/if}</button>{/each}</div>
    {#if pending}<div class="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-warning/25 bg-warning/5 p-4"><p class="text-sm text-warning">{pending} · {t('serverPanel.pending')}</p><div class="flex gap-2"><button type="button" class={button({ variant: 'primary', size: 'sm' })} disabled={busy || running || !pro} onclick={apply}>{t('serverPanel.applyPending')}</button><button type="button" class={button({ variant: 'ghost', size: 'sm' })} disabled={busy || !pro} onclick={() => act(() => serverManage({ action: 'clear_pending', id }), 'serverPanel.applied')}>{t('localServer.cancel')}</button></div></div>{/if}
    {#if kind === 'resourcepack'}<ServerResourcePacks {id} {mcVersion} {running} {pro} onchanged={()=>void load().catch(cause=>error=serverMessage(cause))} />
    {:else if ['mod', 'datapack'].includes(kind)}
        <div class="flex flex-wrap gap-3"><button type="button" class={button({ variant: 'secondary' })} disabled={busy || !pro} onclick={choose}>{t('serverPanel.importFile')}</button><button type="button" class={button({ variant: 'primary' })} disabled={busy || running || !pending || !pro} onclick={apply}>{t('serverPanel.applyPending')} {pending ? `(${pending})` : ''}</button></div>
        {#if kind === 'resourcepack'}<p class="rounded-xl border border-border p-4 text-sm leading-6 text-fg-muted">{t('serverPanel.packUrlHelp')}</p>{/if}
        <form class="flex flex-wrap gap-3" onsubmit={event => { event.preventDefault(); void search(); }}><label class="min-w-36 flex-1"><span class="sr-only">{t('serverPanel.search')}</span><input class="w-full rounded-xl border border-border bg-bg-subtle px-3 py-3 text-sm" placeholder={t('serverPanel.search')} maxlength="120" bind:value={query} /></label><label><span class="sr-only">{t('serverPanel.provider')}</span><select class="rounded-xl border border-border bg-bg-subtle px-3 py-3 text-sm" bind:value={source}><option value="modrinth">Modrinth</option>{#if kind === 'mod'}<option value="curseforge">CurseForge</option>{/if}</select></label><button type="submit" class={button({ variant: 'secondary' })} disabled={busy}>{busy ? t('localServer.loading') : t('serverPanel.search')}</button></form>
        {#each results as result (`${result.source}:${result.sourceId}`)}<article class="flex items-center gap-3 rounded-xl border border-border p-3"><div class="flex h-11 w-11 shrink-0 items-center justify-center overflow-hidden rounded-xl bg-bg-subtle">{#if result.iconUrl}<img src={result.iconUrl} alt="" loading="lazy" decoding="async" class="h-full w-full object-contain" />{/if}</div><div class="min-w-0 flex-1"><h4 class="truncate text-sm font-semibold">{result.title}</h4><p class="mt-1 truncate text-xs text-fg-muted">{result.description}</p></div><button type="button" class={button({ variant: 'secondary', size: 'sm' })} disabled={busy || !pro} onclick={() => act(() => serverManage({ action: 'download_content', id, project: result.sourceId || result.slug, source: result.source, kind }))}>{t('serverPanel.download')}</button></article>{/each}
        {#key kind}<ServerContentCards {id} {kind} items={visible} {running} {busy} {pro} onchange={action=>void act(action,'serverPanel.applied')} />{/key}
    {:else if kind === 'world'}
        <h4 class="text-sm font-semibold">{t('hosting.installedWorld')}</h4>{#if hasWorld}<ServerFileBrowser {id} initialPath="world" />{:else}<p class="rounded-xl border border-dashed border-border p-5 text-sm leading-6 text-fg-muted">{t('hosting.worldNotCreated')}</p>{/if}
        <p class="text-sm leading-6 text-fg-muted">{t('serverPanel.worldHelp')}</p><button type="button" class={button({ variant: 'secondary' })} disabled={busy || running || !pro} onclick={world}>{t('serverPanel.importWorld')}</button>
        {#if confirmWorld}<div class="space-y-3 rounded-xl border border-warning/30 p-4"><p class="text-sm leading-6">{t('serverPanel.worldConfirm')}</p><p class="break-all font-mono text-xs text-fg-muted">{confirmWorld}</p><div class="flex flex-wrap gap-3"><button type="button" class={button({ variant: 'primary' })} disabled={busy || running || !pro} onclick={() => act(async () => { await serverManage({ action: 'import_world', id, path: confirmWorld }); confirmWorld = ''; }, 'serverPanel.applied')}>{t('serverPanel.confirm')}</button><button type="button" class={button({ variant: 'ghost' })} onclick={() => confirmWorld = ''}>{t('localServer.cancel')}</button></div></div>{/if}
    {:else if kind === 'files'}<h4 class="text-sm font-semibold">{t('hosting.fileBrowser')}</h4><ServerFileBrowser {id} /><p class="rounded-2xl border border-border p-5 text-sm leading-7 text-fg-muted">{t('serverPanel.serverPackHelp')}</p><button type="button" class={button({ variant: 'secondary' })} disabled={busy || !pro} onclick={async () => { const path = await open({ multiple: false, filters: [{ name: 'Modrinth', extensions: ['mrpack'] }] }); if (typeof path === 'string') await act(() => serverManage({ action: 'import_modpack', id, path })); }}>{t('serverPanel.importModpack')}</button>
    <button type="button" class={button({ variant: 'secondary' })} disabled={busy || !pro} onclick={async () => { const path = await open({ multiple: false, filters: [{ name: 'Server pack', extensions: ['zip'] }] }); if (typeof path === 'string') await act(() => serverManage({ action: 'import_server_pack', id, path })); }}>{t('serverPanel.importServerPack')}</button>
    <div class="space-y-3 rounded-2xl border border-border p-4"><label class="block space-y-2"><span class="text-sm text-fg-muted">{t('serverPanel.fromInstance')}</span><select class="w-full rounded-xl border border-border bg-bg-subtle p-3 text-sm" bind:value={sourceProfile}><option value="">{t('localServer.selectInstance')}</option>{#each profiles.list.filter(profile => profile.mcVersion === mcVersion) as profile}<option value={profile.id}>{profile.name} · {profile.loader}</option>{/each}</select></label><button type="button" class={button({ variant: 'primary' })} disabled={busy || !pro || !sourceProfile} onclick={() => act(async () => { await serverManage({ action: 'import_instance', id, profileId: sourceProfile }); if (!running) await serverManage({ action: 'apply_content', id }); }, 'serverPanel.applied')}>{busy ? t('localServer.loading') : t('serverPanel.importInstance')}</button><p class="text-xs leading-6 text-fg-muted">{t('serverPanel.importInstanceHelp')}</p></div>
    {#each visible as item, index (`${item.name}:${index}`)}<div class="rounded-xl border border-border p-3"><p class="break-all text-sm">{item.name}</p><p class="mt-1 text-xs text-warning">{t('serverPanel.pending')}</p></div>{/each}
    {:else}<p class="text-sm leading-7 text-fg-muted">{t('serverPanel.filesHelp')}</p><button type="button" class={button({ variant: 'secondary' })} onclick={() => act(() => openLocalServerFolder(id), 'serverPanel.filesHelp')}>{t('localServer.folder')}</button>{/if}
</section>

<style>
.content-kinds{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.content-kind{display:flex;align-items:center;gap:10px;padding:16px 12px;border:1px solid rgb(var(--border));border-radius:13px;background:rgb(var(--bg-subtle));font-size:12px;font-weight:600;transition:background .16s,border-color .16s,transform .16s}.content-kind :global(svg){color:rgb(var(--fg-muted));flex-shrink:0}.content-kind small{margin-left:auto;font-size:10px;border-radius:6px;background:rgb(var(--fg)/.06);padding:3px 6px}.content-kind[aria-pressed=true]{background:rgb(var(--brand-500)/.12);border-color:rgb(var(--brand-400)/.5);color:rgb(var(--brand-400))}.content-kind:hover{border-color:rgb(var(--brand-400)/.5)}.content-kind:focus-visible{outline:2px solid rgb(var(--brand-400));outline-offset:3px}@media(max-width:1150px){.content-kinds{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(prefers-reduced-motion:reduce){.content-kind{transition:none}}
</style>
